SELECT * FROM customer_behaviour.customer;
use customer_behaviour;
DESCRIBE customer;
#    1.....what is a total revenuegenerated by male vs female
SELECT
    gender,
    SUM(`purchase-amount-(usd)`) AS revenue
FROM customer
GROUP BY gender;

#   2.....which customer used a discount but still more than average purchase amount

SELECT
    `customer-id`,
    `purchase-amount-(usd)`
FROM customer
WHERE `discount-applied` = 'Yes'
  AND `purchase-amount-(usd)` >= (
      SELECT AVG(`purchase-amount-(usd)`)
      FROM customer
  );
  
# 3......which are the top 5 products with the highest review rating

SELECT `item-purchased`,round(
    avg(`review-rating`),2) as "Average product rating"
FROM customer
group by `item-purchased`
ORDER BY avg(`review-rating`) DESC
LIMIT 5;

# 4.....compare the average purchase amount between standard and express shopping
select `shipping-type`,
round(avg(`purchase-amount-(usd)`),2)
from customer
where `shipping-type` in ("Standard","Express")
group by `shipping-type`;


#   5...Do subscribed customer more?compare avg spend and total revenue bet subscriber nad non subscriber
SELECT
    `subscription-status`,
    COUNT(`customer-id`) AS total_customer,
    ROUND(AVG(`purchase-amount-(usd)`), 2) AS avg_spend,
    ROUND(SUM(`purchase-amount-(usd)`), 2) AS total_revenue
FROM customer
GROUP BY `subscription-status`
ORDER BY total_revenue DESC, avg_spend DESC;


#    6...which 5 product have the highest percentage of purchase with discount applied

SELECT
    `item-purchased`,
    ROUND(
        SUM(CASE
            WHEN `discount-applied` = 'Yes' THEN 1
            ELSE 0
        END) * 100.0 / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY `item-purchased`
ORDER BY discount_rate DESC limit 5;

#   7.....segment customer into new ,trturning,and loyal based on their total number of previous purchases and show
#the count of each segment
with `customer_type`as(
select `customer-id`,`previous-purchases`,
case 
when `previous-purchases`=1 then "New"
when `previous-purchases` between 2 and 10  then "Returning"
else "Loyal" 
end as `customer_segment`
from customer)

select `customer_segment`,count(*) as "Number of customers"
from `customer_type`
group by `customer_segment`;

#....8....what are the top 3 most purchased product withon each category
with `item_counts` as(
select `category`,
`item-purchased`,
count(`customer-id`)as total_orders,
row_number() over(partition by `category` order by count(`customer-id`)desc) as item_rank
from customer
group by `category`,`item-purchased`
)
select item_rank,`category`,`item-purchased`,total_orders
from `item_counts`
where `item_rank` <=3;

#.....9...are customers who are repeat buyers more than 5 previous purchases
#also  likely to subscribe

select `subscription-status`,
count(`customer-id`) as repeat_buyer
from customer
where `previous-purchases` >5
group by `subscription-status`;

#....10....what is revenue contribution of each age group

select `age_group`,
sum(`purchase-amount-(usd)`) as total_revenue
from customer
group by `age_group`
order by  total_revenue desc;
